<?php /** Performance : passages d'évaluation conservés et usage réel. */ $cur = 'performance'; require __DIR__ . '/_nav.php'; $pc = fn($v) => $v === null ? '—' : number_format((float) $v, 1, ',', ' ') . ' %'; ?>
<div class="row g-3"><div class="col-xl-5"><div class="card mb-3"><div class="card-header">Usage réel (30 jours)</div><div class="card-body small">
  <div class="row g-2"><?php foreach ([['Questions', $live['total']], ['Comprises', $live['understood'] === null ? '—' : $live['understood'] . ' %'], ['Non comprises', (int) ($live['outcomes']['not_understood'] ?? 0)], ['Avis 👍 / 👎', $live['up'] . ' / ' . $live['down']],
      ['Temps moyen', ($speed['avg_ms'] ?? null) !== null ? (int) $speed['avg_ms'] . ' ms' : '—'], ['Temps maximal', ($speed['max_ms'] ?? null) !== null ? (int) $speed['max_ms'] . ' ms' : '—']] as $k): ?>
    <div class="col-6"><div class="border rounded p-2"><div class="text-secondary"><?= e($k[0]) ?></div><b><?= e((string) $k[1]) ?></b></div></div><?php endforeach; ?></div>
  <?php if ($daily): ?><div class="table-responsive"><table class="table table-sm small mt-2 mb-0"><thead><tr><th>Jour</th><th>Questions</th><th>Comprises</th><th>Non comprises</th></tr></thead><tbody><?php foreach (array_slice(array_reverse($daily), 0, 14) as $d): ?><tr><td><?= e(date('d/m', strtotime($d['d']))) ?></td><td><?= (int) $d['n'] ?></td><td><?= (int) $d['ok'] ?></td><td><?= (int) $d['ko'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div>
  <div class="card"><div class="card-header">Passages d'évaluation (détection des régressions)</div><?php if (!$runs): ?><div class="card-body small text-secondary">Aucun passage : lancez « Tests automatiques ».</div><?php else: ?><div class="table-responsive"><table class="table table-sm small mb-0"><thead><tr><th>Date</th><th>Périmètre</th><th>Réussite</th><th>Version</th></tr></thead><tbody>
    <?php $prev = null; foreach ($runs as $r): $rate = $r['phrases'] ? $r['passed'] / $r['phrases'] * 100 : null; ?><tr><td><a href="<?= e(url('/ia/admin/performance', ['run' => $r['id']])) ?>"><?= e(fdate($r['created_at'])) ?></a><div class="text-secondary"><?= e((string) ($r['full_name'] ?? $r['label'])) ?></div></td><td><?= e($r['scope']) ?></td><td><b><?= $pc($rate) ?></b><div class="text-secondary"><?= (int) $r['passed'] ?> / <?= (int) $r['phrases'] ?></div></td><td><?= e((string) $r['version']) ?></td></tr><?php endforeach; ?>
  </tbody></table></div><?php endif; ?></div></div>
<div class="col-xl-7"><?php if ($detail && $detail['metrics']): $s = $detail['metrics']['summary']; ?><div class="card mb-3"><div class="card-header">Passage du <?= e(fdate($detail['run']['created_at'])) ?> — <?= e($detail['run']['scope']) ?></div><div class="card-body small"><div class="row g-2">
  <?php foreach ([['Réussite globale', $pc($s['pass_rate'])], ['Intention reconnue', $pc($s['intent_rate'])], ['Paramètres extraits', $pc($s['slot_rate'])], ['Clarification appropriée', $pc($s['clarify_rate'])], ['Refus approprié', $pc($s['refuse_rate'])],
      ['Formulations vues', $pc($s['seen_rate'])], ['Jamais vues', $pc($s['held_rate'])], ['Taux d\'erreur', $pc($s['error_rate'])], ['Non comprises', $s['not_understood']], ['Temps moyen', $s['avg_ms'] . ' ms'], ['Temps maximal', $s['max_ms'] . ' ms'], ['Formulations', $s['phrases']]] as $k): ?>
    <div class="col-6 col-md-3"><div class="border rounded p-2"><div class="text-secondary"><?= e($k[0]) ?></div><b><?= e((string) $k[1]) ?></b></div></div><?php endforeach; ?></div></div>
  <div class="table-responsive"><table class="table table-sm small mb-0"><thead><tr><th>Domaine</th><th>Scénarios</th><th>Réussite</th><th>Jamais vues</th></tr></thead><tbody><?php foreach ($detail['metrics']['domains'] as $d => $v): ?><tr><td><?= e($d) ?></td><td><?= (int) $v['scenarios'] ?></td><td><?= $pc($v['phrases'] ? $v['pass'] / $v['phrases'] * 100 : null) ?></td><td><?= $pc($v['held_n'] ? $v['held_ok'] / $v['held_n'] * 100 : null) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
  <?php if ($detail['failures']): ?><div class="card"><div class="card-header">Formulations en échec (<?= count($detail['failures']) ?> conservées)</div><div class="table-responsive" style="max-height:420px"><table class="table table-sm small mb-0"><tbody><?php foreach ($detail['failures'] as $f): ?><tr><td><code><?= e($f['code']) ?></code></td><td><?= e($f['q']) ?></td><td><?= e(implode(' ; ', $f['why'])) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
<?php else: ?><div class="alert alert-light border small">Sélectionnez un passage pour voir son détail.</div><?php endif; ?></div></div>
<p class="small text-secondary mt-3">Le taux « jamais vues » porte sur des formulations (fautes, autres tournures) que le classifieur n'a pas reçues en exemple : c'est lui qui indique si l'assistant généralise. Un taux élevé sur les seules formulations vues ne prouve rien.</p>
